-- Peelr September 2026 questions: STRANGERS
-- Theme: New Beginnings, a fresh start. Meeting someone new right as a new season starts.
-- Depth is capped at curious getting-to-know-you: never assumes a stranger has earned raw trauma disclosure.
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
